# protocol ids: contiguous port-local band 429..461. The in-flight plan's
# 237..269 band COLLIDES: to_u16 already owns 250 (AngryNimbus) and render_key
# owns 261/263/264/265 (FungiSpore/PlanterasHook/PlanterasTentacle/Spore). The
# combined free band (to_u16 max 353, render_key lunar ids <= 549) is 429..488;
# we take the first 33 (the pirate/wyvern renumber precedent). Verified free in
# to_u16, from_u16 AND render_key (probe3/probe10/probe16).
for i, k in enumerate(KINDS):
    k['proto'] = 429 + i
# 5 kinds per commit (the W4-d35 dispatch rule), 33 kinds -> 7 batches.
BATCHES = [KINDS[i:i+5] for i in range(0, len(KINDS), 5)]
